def the_profane_slaughter_the_blood_and_the_gates(case, data):
    """F4 — Deut 12:15-19 — THE RELEASE SAID IN NEW WORDS (12:15 — THE LINE profane_slaughter_permitted writing profane_slaughter_permitted, holy_things_in_the_gates_barred and levite_forsaking_barred): the unclean and the clean, the blemished consecrated (Mishnah Bekhorot 2:2-3; Bekhorot 15a-16a, 33a-b), the eaters, the blood like water (Chullin 84a; Mishnah Makhshirin 6:4); THE GATES' BAR (12:17 — the ladder of a fortiori Makkot 17a-19b, the list read backward, the lashes Mishnah Makkot 3:3, the impure tithe's warning from the chapter's own gates, THE TWO TITHES); before the LORD you shall eat it (12:18); THE LEVITE (12:19 — the verse alone; the scope 74:8-9)"""
    del P_[:]
    ask = case['ask']
    if ask == 'with_all_the_desire_of_your_soul':
        ink('12:15', '"ONLY, WITH ALL THE DESIRE OF YOUR SOUL YOU MAY SLAUGHTER AND EAT FLESH according to the blessing of the LORD your God which He has given you, IN ALL YOUR GATES" — "with all the desire of your soul" %s (12:15, 12:20, 12:21 — the chapter\'s three, the Bible\'s three); the shared run with Leviticus 17:3 %d, 17:4 %d, 17:5 %d (ONE token in order — THE RELEASE SAID IN NEW WORDS); "you may slaughter" %s; "in all your gates" %s' % (P('בכל', 'אות', 'נפשך'), SH(D12(15), ('Lev', 17, 3)), SH(D12(15), ('Lev', 17, 4)), SH(D12(15), ('Lev', 17, 5)), P('תזבח', 'ואכלת', 'בשר'), P('בכל', 'שעריך')))
        move('cold_run_sanctions (CALL) — SA.outside(individual) = %s, SA.outside(common_inside) = %s; the Sifrei 71:1-2, 75:3-4; Chullin 16b:14-17a:4 (read whole at the docket)' % (SA_IND['v'], SA.outside('common_inside')['v']), "A LAW CHANGED BY A PLACE — Leviticus 17:3-5's tent-door rule (the flesh of desire brought as a peace offering to the door; 'blood shall be reckoned' — SA.outside by CALL) RELEASED for the Land: 'only … you may slaughter and eat flesh in all your gates'; CONDITIONAL ON THE ENTRY — the_wilderness_flesh's arms (R. Yishmael: forbidden in the wilderness, released at the entry, the distance its ground; R. Akiva: never forbidden, the stabbed flesh permitted in the wilderness, the rite required at the entry; the exile's third state — 'one may always slaughter'); 'according to the blessing' — the civility's ladder (F5)")
        dat('THE LINE profane_slaughter_permitted — STATUTE by form, at the counter\'s own day %s after place_chosen_declared, NO marker; THE WRITE profane_slaughter_permitted — a STATUS on israel_people CONDITIONAL on the entry (DD2, DD4; the parameter the_wilderness_flesh read: %s); the readback row 12:15 — EXPANDED by CALL (SA.outside — one token in order with Leviticus 17:3)' % (CLOCK['counter'], CLOCK['flesh_arms']))
        return out("with all the desire of your soul (12:15) — Leviticus 17:3-5's tent-door rule released for the Land in new words (one token in order; SA.outside by CALL — the readback row EXPANDED): THE WRITE profane_slaughter_permitted — a STATUS on Israel conditional on the entry (the_wilderness_flesh's arms — R. Yishmael's release, R. Akiva's rite, the exile's third state); THE LINE profane_slaughter_permitted at the counter's day", ['profane_slaughter_permitted'])
    if ask == 'the_unclean_and_the_clean':
        ink('12:15', '"THE UNCLEAN AND THE CLEAN MAY EAT IT, AS THE GAZELLE AND AS THE HART" — "the unclean and the clean" %s (12:15, 12:22, 15:22 — the three seats); "as the gazelle and as the hart" %s (12:15, 12:22, 15:22 the same three); the gazelle\'s homograph %s (the noun\'s lemma seats — "the gazelle" and "the splendor" one string)' % (P('הטמא', 'והטהור'), P('כצבי', 'וכאיל'), len(U('צבי', 'הצבי', 'כצבי', 'וצבי'))))
        move('the Sifrei 71:3-6; Bekhorot 15a:5, 15a:20, 33a:1-5 (read whole at the docket)', "'THE UNCLEAN AND THE CLEAN' — 12:15's 'the impure' UNQUALIFIED: the impure person and the pure eat from one dish (71:4); 'as the gazelle and as the hart' — THE THREE SEATS of the comparison (Bekhorot 33a:1-5 — I1 checked in MIDDOT.md: 12:15 the profane, 12:22 the general rule, 15:22 the blemished firstling): the gazelle and the hart's flesh eaten by the impure, no gifts to the priest from them, no covering here (the domestic animal — 71:14); THE GAZELLE'S HOMOGRAPH a DATA row (the splendor's string)")
        dat('the readback row 12:22 — VARIANT by CALL (SA.covering); the gazelle\'s homograph a DATA row; the exam\'s person the impure who eats the profane flesh with the pure from one dish: accepted (71:4)')
        return out("the unclean and the clean (12:15) — 'the impure' unqualified: the impure and the pure eat from one dish (the Sifrei 71:4); 'as the gazelle and as the hart' the comparison's three seats (Bekhorot 33a:1-5): the impure who eats the profane flesh with the pure accepted", ['accepted'])
    if ask == 'the_blemished_consecrated':
        ink('12:15', '"ONLY … you may slaughter and eat flesh … the unclean and the clean may eat it, as the gazelle and as the hart" — "only" %s (the chapter\'s four: 12:15, 12:16, 12:23, 12:26) bounding; 15:22\'s blemished firstling %s the kin' % ([v for v in range(1, 32) for x in W12(v) if x == 'רק'], P('הטמא', 'והטהור', 'יחדו', 'כצבי', 'וכאיל')))
        move('Mishnah Bekhorot 2:2-3 (the exam); Bekhorot 15b:9-12, 15a:6-8, 15a:13-17, 15b:1, 33b:20 (read whole at the docket); the Sifrei 71:1-6', "THE BLEMISHED CONSECRATED'S TABLE — the blemish before the consecration: 'only the mitzva (commandment) of value' (redeemed and sold in the market, weighed by the pound); the consecration before the blemish: 'ONLY THE PERMISSION OF CONSUMPTION' — not sold in the market nor weighed, no shearing nor labor, the offspring and the milk forbidden (Mishnah Bekhorot 2:2-3 — Bekhorot 15b:9-12: 12:15's release read on the redeemed animal); 'as the gazelle and the hart' EXCLUDES the firstborn and the gifts — 'however' bounding (15a:6-8); the fat from 'its blood' so its karet (excision) stands (15a:13-17); 'you may slaughter and eat' the permission from the slaughter (15b:1); 33b:20 the firstling's blemish")
        dat('the blemished consecrated the docket\'s crown (D2b — the exam\'s rows Mishnah Bekhorot 2:2-3); the exam\'s person the one who slaughters the blemished consecrated after its redemption — the permission of consumption alone, no shearing, no market: accepted (15b:12)')
        return out("the blemished consecrated (12:15) — the consecration before the blemish 'only the permission of consumption' (Mishnah Bekhorot 2:2-3; Bekhorot 15b:9-12): 12:15's release read on the redeemed animal; the firstborn and the gifts excluded by 'as the gazelle and the hart' (15a:6-8): the one who slaughters the redeemed blemished consecrated accepted — consumption alone", ['accepted'])
    if ask == 'the_eaters':
        ink('12:15', '"THE UNCLEAN AND THE CLEAN may eat it" — 12:15\'s "the impure" %s against Numbers 9:10\'s qualified "impure by a corpse" %s' % (P('הטמא', 'והטהור', 'יאכלנו'), P('טמא', 'לנפש')))
        move('Bekhorot 33a:4, 33a:8-11, 33b:16 (read whole at the docket)', "THE EATERS — R. Akiva: 'the impure and the pure' includes a GENTILE who eats the redeemed consecrated? the comparison's third seat (33a:4); BEIT SHAMMAI / BEIT HILLEL on the blemished firstling — 12:15's 'THE IMPURE' UNQUALIFIED, unlike Numbers 9:10's 'impure by a corpse' (33a:8-11 — the impure of any kind eats); 33b:16 the a fortiori (I1) on the firstling's flesh")
        dat('the eaters a DATA row (the docket\'s find); the exam\'s person the impure who eats the profane flesh — accepted (33a:8-11; 71:4)')
        return out("the eaters (12:15) — 'the impure' unqualified against Numbers 9:10's 'impure by a corpse' (Bekhorot 33a:8-11 — Beit Shammai / Beit Hillel); a gentile's eating the comparison's third seat (33a:4): the impure who eats the profane flesh accepted", ['accepted'])
    if ask == 'the_blood_like_water':
        ink('12:16', '"ONLY THE BLOOD YOU SHALL NOT EAT; ON THE EARTH YOU SHALL POUR IT LIKE WATER" — the clause %s (12:16, 12:24 — the two seats; 12:24 in the singular); "like water" %s; the one plural verb in the singular half %s (12:16\'s "you shall not eat" plural — a DATA row)' % (P('על', 'הארץ', 'תשפכנו', 'כמים'), P('כמים'), [(x, m) for x, m in wm('Deut', 12, 16) if m and '2mp' in m]))
        move('cold_run_sanctions (CALL) — SA.blood(ban) = %s, SA.blood(which_blood) = %s, SA.covering(hunted_of_any_kind) = %s, SA.covering(consecrated) = %s; Chullin 84a:10-16, 33a:12, 35b:15; Pesachim 22a:8; Mishnah Makhshirin 6:4 (read whole at the docket); the Sifrei 71:13-14' % (SA_BAN['v'], SA_WHICH['v'], SA_HUNTED['v'], SA_CONSEC['v']), "'LIKE WATER' FOUR WAYS (71:14) — NO COVERING for the domestic animal (Chullin 84a:10-11 — Leviticus 17:13's dust for the hunted alone: SA.covering by CALL, the hunted of any kind covered, the consecrated not); BENEFIT permitted like water (Pesachim 22a:8); SUSCEPTIBILITY to impurity like water (Chullin 33a:12 — Mishnah Makhshirin 6:4); the disqualified consecrated's blood like water (35b:15); but NO IMMERSION in blood (84a:12-16 — Leviticus 11:36's three waters exclude it: a fifth reading refused); ONE PROHIBITION, NOT TWO (71:13 — 12:16 and 12:24 one 'you shall not eat'); the blood's ban karet (SA.blood by CALL — the lifeblood alone for the sages, any blood for R. Yehuda)")
        dat('the readback rows 12:16 (VARIANT by CALL — SA.blood, SA.covering) and 12:24 (VERBATIM in kind by CALL); "like water" four ways a DATA row; the exam\'s person the one who covers the blood of his ox — no covering for the domestic animal: accepted (84a:11)')
        return out("the blood like water (12:16, 12:24) — four ways (the Sifrei 71:14): no covering for the domestic animal (Chullin 84a:10-11; SA.covering by CALL), benefit (Pesachim 22a:8), susceptibility (Chullin 33a:12 — Mishnah Makhshirin 6:4), no immersion (84a:12-16); one prohibition, not two (71:13); the ban karet (SA.blood by CALL): the one who covers his ox's blood accepted — no covering needed", ['accepted'])
    if ask == 'you_may_not_eat_within_your_gates':
        ink('12:17', '"YOU MAY NOT EAT WITHIN YOUR GATES the tithe of your grain, your wine and your oil, the firstlings of your herd and of your flock, all your vows which you vow, your freewill offerings and the heave offering of your hand" — "you may not" %s (read "you are not permitted", 72:1); "the tithe of your grain, your wine and your oil" %s (12:17 and 14:23 — THE SECOND TITHE\'S FIRST SEAT); the tithe STARRED by the parser %s; the list\'s seven items' % (P('לא', 'תוכל', 'לאכל'), P('מעשר', 'דגנך', 'ותירשך', 'ויצהרך'), MARKS(12, 17)))
        move('cold_run_korach (CALL) — KR.the_tithe(every_place) = %s; the Sifrei 72:1-8; Mishnah Makkot 3:3 (the exam); Makkot 13a-b (credited whole from the refuge docket)' % (KR_EVERY[0][:60],), "THE GATES' BAR — 'you may not' is 'you are not permitted' (72:1 — Onkelos the same; R. Yehoshua ben Korcha's 'you can, but you are not permitted'); the seven items each a bar of its own (72:2-8 — the second tithe, the firstling, the sin and guilt offerings from 'the firstlings of your herd', the peace offerings from 'your vows', the thanks offering from 'your freewill offerings', the first fruits from 'the heave offering of your hand'); THE SECOND TITHE'S FIRST SEAT — 14:22-26 ahead; the firstling's eating 15:19-23 ahead; Numbers 18:31's 'in every place' the Levites' tithe eaten anywhere against this (KR by CALL — THE TWO TITHES)")
        dat('THE WRITE holy_things_in_the_gates_barred — a BLOCK on israel_people at the counter\'s day (DD2, DD4): the code\'s hole compiled; the readback row 12:17 SUPPLIED AS A LAW WITH THE WRITE (the second tithe\'s first seat); the tithe starred by the parser a DATA row (the reading\'s measurement)')
        return out("you may not eat within your gates (12:17) — 'you are not permitted' (the Sifrei 72:1); the seven items each a bar (72:2-8); the second tithe's first seat (14:22-26 ahead), the Levites' tithe eaten anywhere the opposite (Num 18:31 — KR.the_tithe('every_place') by CALL): THE WRITE holy_things_in_the_gates_barred — a BLOCK on Israel at the chapter's own day; the readback row SUPPLIED AS A LAW with its write", ['holy_things_in_the_gates_barred'])
    if ask == 'the_ladder_of_a_fortiori':
        ink('12:17', '"the tithe … the firstlings … your vows … your freewill offerings … the heave offering of your hand" — the list\'s order the ladder\'s rungs; the items in the verse %s' % ([x for x in W12(17)][4:],))
        move('Makkot 17a:12-17b:1, 17b:3-8, 18a:1-2 (read whole at the docket); the Sifrei 72:9-11, 73:1, 74:1; Keritot 4b:29-5a:2 (read whole at the docket)', "THE LADDER OF A FORTIORI AT ITS BAVLI SEAT — R. Shimon's five rungs on 12:17's list (Makkot 17a:12-17b:1; I1 checked in MIDDOT.md): the second tithe of grain lashed for the outside, the firstling a fortiori; the firstling lashed for the non-priest, the vows (the peace offerings) a fortiori …; RAVA'S REFUTATIONS of each rung (17b:3-8 — the stringencies of the lesser); 18a:1-2 — Rava: THE REPETITION DESIGNATES, not the a fortiori (each item named for its own prohibition; the Sifrei 72:9-11, 73:1, 74:1 the decision table); the lashes per type (Keritot 4b:29-5a:2)")
        dat('the ladder a DATA row (the design predicted the decision table; D2b found the Bavli seat); the exam\'s person the one who eats the vows\' flesh outside the curtains — lashed by its own name, not by the ladder (18a:1): accepted')
        return out("the ladder of a fortiori (12:17) — R. Shimon's five rungs on the list (Makkot 17a:12-17b:1), Rava's refutations (17b:3-8), the repetition designates (18a:1-2; the Sifrei 72:9-11, 73:1, 74:1): the one who eats the vows' flesh outside the curtains accepted — lashed by its own name", ['accepted'])
    if ask == 'the_list_read_backward':
        ink('12:17', '"… the firstlings of your herd and of your flock, all your vows which you vow, your freewill offerings and the heave offering of your hand" — the list in the verse\'s order; read backward the derivation runs the other way')
        move('Makkot 17b:9, 17b:10 (read whole at the docket)', "THE LIST READ BACKWARD — the tanna (the Mishnah-era teacher) reads 12:17's list from its end: the heave offering of the hand (the first fruits) the source, and each item derived from the one after it (17b:9 — the list read backward, named in MIDDOT's entry, no code); 17b:10 A MERE PROHIBITION from the inference — no punishment from an inference (the rider on I1: one does not punish by an a fortiori)")
        dat('the list read backward named (no code) — MIDDOT\'s docket entry; the exam\'s person the one who eats the first fruits outside the wall — the source item, lashed by its own verse (17b:9): accepted')
        return out("the list read backward (12:17) — the first fruits the source, each item derived from the next (Makkot 17b:9); no punishment from an inference (17b:10): the one who eats the first fruits outside the wall accepted — lashed by its own verse", ['accepted'])
    if ask == 'the_lashes_outside_the_wall':
        ink('12:17', '"you may not eat within your gates the tithe" — the second tithe outside the wall: 14:23\'s "before the LORD your God in the place" %s; Mishnah Makkot 3:3 the answer sheet' % (P('לפני', 'יהוה', 'אלהיך', 'במקום', 'אשר', 'יבחר'),))
        move('Mishnah Makkot 3:3 (the exam — at 13a); Makkot 13a-13b (credited whole from the refuge docket); Makkot 19b:15 (read whole at the docket)', "THE LASHES — 'these are the ones who are flogged: … one who eats the second tithe or the firstling outside the wall, the lesser holy things or the second tithe outside the wall' (Mishnah Makkot 3:3 — 12:17's bar the source); THE BAR'S ONSET AT THE WALL (19b:15 — 12:18 read with 12:17: 'before the LORD you shall eat it' the wall's inside); a prohibition with an act — flogged")
        dat('the exam\'s person the one who eats the second tithe outside the wall — FLOGGED (Mishnah Makkot 3:3): lashes; the scene counts two lashes persons this chapter (the erasure\'s and this)')
        return out("the lashes outside the wall (12:17) — one who eats the second tithe or the firstling outside the wall is flogged (Mishnah Makkot 3:3; the bar's onset at the wall, Makkot 19b:15): the one who eats the second tithe outside the wall lashed", ['lashes'])
    if ask == 'the_impure_tithes_warning':
        ink('12:15-17', '"THE IMPURE AND THE PURE may eat it … IN ALL YOUR GATES" (12:15) against "YOU MAY NOT EAT WITHIN YOUR GATES the tithe" (12:17) — "your gates" in the chapter %s; 12:21\'s "too far" %s' % ([v for v in range(1, 32) for x in W12(v) if x in ('בשעריך', 'בשעריכם', 'שעריך')], P('כי', 'ירחק', 'ממך', 'המקום')))
        move('Makkot 19b:3-7, 19b:9-13, 19a:3-5, 19a:7, 19a:10 (read whole at the docket)', "THE IMPURE TITHE'S WARNING FROM THE CHAPTER'S OWN GATES — the warning for eating the second tithe in impurity read from 12:15's 'the impure … within your gates' against 12:17's 'you may not eat within your gates' (19b:3-7 — the tithe eaten in your gates when impure is the profane's permission, barred for the tithe); 'TOO FAR' AS ANY INABILITY — 'when the place is too far … unable to carry it' (14:24): one stride outside the wall (19b:9-13 — 'from you' from your fullness); THE SECOND TITHE AND THE TEMPLE — juxtaposed to the firstborn at 14:23 (19a:3-5); the common element refuted (19a:7 — I3); the chain rule (19a:10)")
        dat('the impure tithe\'s warning the docket\'s crown (D2b — the chapter\'s own gates the source); the exam\'s person the one who takes one stride outside the wall with the tithe — outside (19b:9-13): accepted')
        return out("the impure tithe's warning (12:15-17) — 12:15's 'the impure … within your gates' against 12:17's 'you may not eat within your gates' (Makkot 19b:3-7); 'too far' as any inability, one stride outside the wall (19b:9-13); the second tithe and the Temple (19a:3-10): the one who takes one stride outside the wall accepted — outside", ['accepted'])
    if ask == 'the_two_tithes':
        ink('12:17', '"the tithe of your grain, your wine and your oil" barred from the gates against Numbers 18:31 "you shall eat it IN EVERY PLACE, you and your households" — "in every place" %s (Num 18:31 and Deut 12:13 — the same two tokens); "the tithe" in the chapter %s' % (P('בכל', 'מקום'), [v for v in range(1, 32) for x in W12(v) if x.startswith('מעשר')]))
        move('the tape (the recon): tithe_of_the_tithe_commanded at Num 18:25-32 (the-levites — FOUND by kind and first verse); cold_run_korach (CALL) — KR.the_tithe(every_place) = %s, KR.the_tithe(exclusion_table) = %s; the Sifrei 77:7-8' % (KR_EVERY[0][:70], KR_EXCL[0][:40]), "THE TWO TITHES — Numbers 18:31's 'in every place' THE LEVITES' TITHE EATEN ANYWHERE, even in a cemetery (Sifrei Bamidbar 122:1; Yevamot 86b — KR by CALL; tithe_granted on the Levites UNMOVED) against 12:17's SECOND TITHE AT THE PLACE (the owner's, the first fruits' kin — 14:22-26); the Levites' tithe the first, the owner's the second: two tithes, two places; the tithe's joint owners (77:7-8)")
        dat('THE TWO TITHES a DATA row (the_two_tithes — asserted on the DB: Num 18:31 "in every place", Deut 12:17 the second tithe\'s first seat); the exam\'s person the Levite who eats his tithe in a cemetery — the first tithe anywhere: accepted (Sifrei Bamidbar 122:1)')
        return out("the two tithes (12:17) — the Levites' first tithe eaten in every place (Num 18:31 — KR.the_tithe('every_place') by CALL; tithe_granted unmoved) against the owner's second tithe at the place (12:17 the first seat; 14:22-26): the Levite who eats his tithe in a cemetery accepted", ['accepted'])
    if ask == 'before_the_lord_you_shall_eat_it':
        ink('12:18', '"BUT BEFORE THE LORD YOUR GOD YOU SHALL EAT IT, in the place which the LORD your God will choose — you and your son and your daughter, your manservant and your maidservant, and the Levite within your gates — and you shall rejoice before the LORD your God in all that you put your hand to" — the singular list %s; the shared run with 16:11 %d (THIRTEEN — the chapter\'s closest kin), with 5:14 %d' % (P('אתה', 'ובנך', 'ובתך', 'ועבדך', 'ואמתך', 'והלוי'), SH(D12(18), ('Deut', 16, 11)), SH(D12(18), ('Deut', 5, 14))))
        move('cold_run_covenant_at_horeb (CALL) — CH.the_first_tablet(the_servants_rest) = %s; the Sifrei 74:2-4; Makkot 19b:15' % (CH_SERV[0][:50],), "'BEFORE THE LORD YOU SHALL EAT IT' — Shiloh and Jerusalem (74:2-3 — the place's two names at the eating); the dearer first (74:4 — the son before the servant, the Levite last); 5:14's household said again (CH.the_first_tablet by CALL — the readback row 12:18 VERBATIM in kind); the bar's onset at the wall (Makkot 19b:15 — 12:18 read with 12:17); 16:11's thirteen tokens the feast's own")
        dat('the readback row 12:18 — VERBATIM in kind by CALL (CH.the_first_tablet — 5:14\'s list); the rejoicing\'s status by kind (12:7\'s write); the exam\'s person the one who eats the second tithe in his gates before the pilgrimage — the place alone: accepted against')
        return out("before the LORD you shall eat it (12:18) — the place (Shiloh and Jerusalem — the Sifrei 74:2-3), the household 5:14's (CH.the_first_tablet by CALL — the readback row VERBATIM in kind), the dearer first (74:4): the one who eats the second tithe in his gates accepted against — the place alone", ['accepted'])
    if ask == 'lest_you_forsake_the_levite':
        ink('12:19', '"TAKE HEED TO YOURSELF LEST YOU FORSAKE THE LEVITE all your days on your land" — the verse ALONE in the Bible: "lest you forsake the Levite" the one seat %s; "all your days" %s; "on your land" %s; the Levite\'s seats in the chapter %s' % (P('פן', 'תעזב', 'את', 'הלוי'), P('כל', 'ימיך'), P('על', 'אדמתך'), [v for v in range(1, 32) for x in W12(v) if x == 'והלוי']))
        move('the Sifrei 74:6-7 (read whole at the reading); Pesachim 8b:7-9 (credited from 9b\'s docket)', "THE LEVITE — a prohibition by the shelf's reading of 'take heed … lest' (74:6-7 — 'take heed' a negative command, 'lest' a negative command); the Levite's pilgrimage (Pesachim 8b — the Levite with no land and the pilgrimage's guard); the Levite within your gates at the rejoicing (12:12, 12:18 — the dearer first); 'no portion nor inheritance' (18:20 — portion_declared on the tape) the reason")
        dat('THE WRITE levite_forsaking_barred — a BLOCK on israel_people at the counter\'s day (DD2, DD4): the code\'s hole compiled; the readback row 12:19 SUPPLIED AS A LAW WITH THE WRITE (the verse alone in the Bible — a DATA row)')
        return out("lest you forsake the Levite (12:19) — the verse alone in the Bible; a prohibition by 'take heed … lest' (the Sifrei 74:6-7): THE WRITE levite_forsaking_barred — a BLOCK on Israel at the chapter's own day; the readback row SUPPLIED AS A LAW with its write", ['levite_forsaking_barred'])
    if ask == 'the_levites_scope':
        ink('12:19', '"ALL YOUR DAYS ON YOUR LAND" — the bar\'s two scopes: "all your days" %s and "on your land" %s' % (P('כל', 'ימיך', 'על', 'אדמתך'), U('אדמתך', books=('Deut',))))
        move('the Sifrei 74:8-9 (read whole at the reading)', "THE LEVITE'S SCOPE — 'all your days': even in the sabbatical years and the jubilees, when the gifts of the field fail (74:8); 'on your land': in the Land, NOT IN THE EXILE (74:9) — the bar's edge; the ladder of support (69:4, 74:5) the Levite's gifts the means")
        dat('the exam\'s person the one who forsakes the Levite in the exile — EXEMPT (74:9: "on your land" and not in the exile); the sabbatical\'s Levite the other arm (74:8): the bar holds')
        return out("the Levite's scope (12:19) — 'all your days' even in sabbaticals and jubilees (the Sifrei 74:8), 'on your land' not in the exile (74:9): the one who forsakes the Levite in the exile exempt", ['exempt'])
