    ask = case['ask']
    if ask == 'the_table':
        ink('12:1-31', 'thirty-one verses, thirty-one rows — one per verse; THE CHAPTER SWITCHES NUMBER AT ITS MIDDLE — the register PLURAL only in %d verses, SINGULAR only in %d, BOTH in %d, NEITHER in %d' % (sum(1 for v, (p, s) in NUM.items() if p and not s), sum(1 for v, (p, s) in NUM.items() if s and not p), sum(1 for v, (p, s) in NUM.items() if p and s), sum(1 for v, (p, s) in NUM.items() if not p and not s)))
