        dat('every reference row\'s entry FOUND (the tape lines by kind and first verse; every kin cell answering) — asserted on the module; no hole, no open row, no stretch, no retrograde row')
        return out("the table — thirty-one rows, one per verse: the grades %s; %d on the tape by kind and first verse, %d in the kin's cells by CALL, %d SUPPLIED (the state row and the five law rows with their writes); no hole, no open row, no stretch, no retrograde row" % (dict(sorted(RB_GRADES.items())), sum(1 for r in READBACK if r['tape_kind']), sum(1 for r in READBACK if r['cell']), sum(1 for r in READBACK if r['grade'] == 'SUPPLIED')), ['accepted'])
